// Auto-generated from Sales_CRM_Web/src/assets/singularity-teach-logo.png — the TEACH-mode
// wordmark used on the header of every generated Sales Document PDF (Quotation / Purchase
// Order / Tax Invoice), matching web pixel-for-pixel. Base64 rather than a bundled asset file
// because react-native-html-to-pdf's WebView cannot reliably resolve a Metro asset path —
// a data URI works everywhere the HTML itself does.
export const teachLogoBase64 = '';
export const teachLogoDataUri = `data:image/png;base64,${teachLogoBase64}`;
